local OrganPipeMaker = {}
local PRODUCTS = {
    wooden_pipe = { name = "Lesena piščal", woodCost = 2, time = 2, cost = 30, soundQuality = 8, description = "Preprosta lesena orgelska piščal." },
    tin_pipe = { name = "Kositrna piščal", tinCost = 2, time = 3, cost = 80, soundQuality = 12, prestige = 2, description = "Kositrna piščal z močnim tonom." },
    lead_pipe = { name = "Svinčena piščal", leadCost = 2, time = 4, cost = 130, soundQuality = 14, prestige = 3, description = "Svinčena piščal z bogatim zvokom." },
    brass_pipe = { name = "Medeninasta piščal", brassCost = 2, time = 5, cost = 280, soundQuality = 18, prestige = 6, happiness = 1, description = "Medeninasta piščal za principe." },
    silver_pipe = { name = "Srebrna piščal", silverCost = 2, time = 7, cost = 600, soundQuality = 24, prestige = 12, happiness = 2, description = "Srebrna piščal za kraljevske orgle." },
    royal_organ_rank = { name = "Kraljevski orgelski register", goldCost = 2, silverCost = 2, tinCost = 2, time = 12, cost = 1800, soundQuality = 40, prestige = 45, happiness = 8, description = "Veliki kraljevski orgelski register z zlatimi in srebrnimi piščalmi." },
}
local BUILDINGS = {
    workshop = { name = "Piščalna delavnica", cost = { gold = 280, wood = 130 }, upkeep = 7, qualityBonus = 5 },
    metal_room = { name = "Kovinska soba", cost = { gold = 900, wood = 220, stone = 200, tin = 6 }, upkeep = 22, qualityBonus = 18 },
    voicing_room = { name = "Intonirnica", cost = { gold = 1900, wood = 300, stone = 400, silver = 25, lead = 8 }, upkeep = 45, qualityBonus = 30 },
    royal_pipe_atelier = { name = "Kraljevski atelje piščali", cost = { gold = 7500, wood = 600, stone = 800, gold = 80, silver = 30 }, upkeep = 140, qualityBonus = 55, prestigeBonus = 35 },
}
OrganPipeMaker.woodStock = 14; OrganPipeMaker.tinStock = 10; OrganPipeMaker.leadStock = 10; OrganPipeMaker.brassStock = 8; OrganPipeMaker.silverStock = 8; OrganPipeMaker.goldStock = 6
OrganPipeMaker.productStock = {}; OrganPipeMaker.buildings = {}; OrganPipeMaker.maker = nil; OrganPipeMaker.activeMaking = {}; OrganPipeMaker.totalProducts = 0; OrganPipeMaker.dayTimer = 0
function OrganPipeMaker.init() OrganPipeMaker.woodStock=14; OrganPipeMaker.tinStock=10; OrganPipeMaker.leadStock=10; OrganPipeMaker.brassStock=8; OrganPipeMaker.silverStock=8; OrganPipeMaker.goldStock=6; OrganPipeMaker.productStock={}; OrganPipeMaker.buildings={}; OrganPipeMaker.maker=nil; OrganPipeMaker.activeMaking={}; OrganPipeMaker.totalProducts=0; OrganPipeMaker.dayTimer=0; print("[OrganPipeMaker] Royal Organ Pipe Maker System initialized (6 products, 4 buildings)") end
function OrganPipeMaker.hireMaker(n,s) s=s or math.random(50,90); local c=500+s*10; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; OrganPipeMaker.maker={name=n or ("Piščalar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Piščalar najet: %s (spretnost: %d)",OrganPipeMaker.maker.name,s),"success") end; return true end
function OrganPipeMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function OrganPipeMaker.build(id) local ok,e=OrganPipeMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(OrganPipeMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function OrganPipeMaker.getQualityBonus() local b=0; for _,bd in ipairs(OrganPipeMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function OrganPipeMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.woodCost and OrganPipeMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.tinCost and OrganPipeMaker.tinStock<(d.tinCost or 0) then return false,"Premalo kositra" end; if d.leadCost and OrganPipeMaker.leadStock<(d.leadCost or 0) then return false,"Premalo svinca" end; if d.brassCost and OrganPipeMaker.brassStock<(d.brassCost or 0) then return false,"Premalo medenine" end; if d.silverCost and OrganPipeMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and OrganPipeMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if #OrganPipeMaker.buildings==0 then return false,"Potrebna delavnica" end; if not OrganPipeMaker.maker then return false,"Potreben piščalar" end; return true end
function OrganPipeMaker.make(pt,qty) qty=qty or 5; local ok,e=OrganPipeMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.woodCost then OrganPipeMaker.woodStock=OrganPipeMaker.woodStock-d.woodCost*qty end; if d.tinCost then OrganPipeMaker.tinStock=OrganPipeMaker.tinStock-d.tinCost*qty end; if d.leadCost then OrganPipeMaker.leadStock=OrganPipeMaker.leadStock-d.leadCost*qty end; if d.brassCost then OrganPipeMaker.brassStock=OrganPipeMaker.brassStock-d.brassCost*qty end; if d.silverCost then OrganPipeMaker.silverStock=OrganPipeMaker.silverStock-d.silverCost*qty end; if d.goldCost then OrganPipeMaker.goldStock=OrganPipeMaker.goldStock-d.goldCost*qty end; local t=d.time; if OrganPipeMaker.maker then t=math.max(1,t-math.floor(OrganPipeMaker.maker.skill/12)) end; table.insert(OrganPipeMaker.activeMaking,{id="pipe_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,soundQuality=d.soundQuality or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function OrganPipeMaker.completeMaking(m) local q=1.0+(OrganPipeMaker.getQualityBonus()/100); if OrganPipeMaker.maker then q=q+(OrganPipeMaker.maker.skill/180) end; q=math.min(2.0,q); OrganPipeMaker.productStock[m.productType]=(OrganPipeMaker.productStock[m.productType] or 0)+m.quantity; OrganPipeMaker.totalProducts=OrganPipeMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if OrganPipeMaker.maker then OrganPipeMaker.maker.itemsMade=OrganPipeMaker.maker.itemsMade+m.quantity; if math.random()<0.20 then OrganPipeMaker.maker.skill=math.min(100,OrganPipeMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Piščali izdelane: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"organpipe.completed",{productName=m.productName,soundQuality=m.soundQuality}) end end
function OrganPipeMaker.update(dt) if not _G.state then return end; OrganPipeMaker.dayTimer=OrganPipeMaker.dayTimer+dt; if OrganPipeMaker.dayTimer>=30 then OrganPipeMaker.dayTimer=0; for i=#OrganPipeMaker.activeMaking,1,-1 do local m=OrganPipeMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then OrganPipeMaker.completeMaking(m); table.remove(OrganPipeMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(OrganPipeMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if OrganPipeMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function OrganPipeMaker.getStats() return {woodStock=OrganPipeMaker.woodStock,tinStock=OrganPipeMaker.tinStock,leadStock=OrganPipeMaker.leadStock,brassStock=OrganPipeMaker.brassStock,silverStock=OrganPipeMaker.silverStock,goldStock=OrganPipeMaker.goldStock,productStock=OrganPipeMaker.productStock,numBuildings=#OrganPipeMaker.buildings,hasMaker=OrganPipeMaker.maker~=nil,makerName=OrganPipeMaker.maker and OrganPipeMaker.maker.name or "—",makerSkill=OrganPipeMaker.maker and OrganPipeMaker.maker.skill or 0,activeMaking=#OrganPipeMaker.activeMaking,totalProducts=OrganPipeMaker.totalProducts} end
return OrganPipeMaker
